15	// runDiagHost runs a command in an ephemeral container with --network host
16	func runDiagHost(image string, args []string) DiagResult {
17		if _, err := exec.LookPath("docker"); err != nil {
18			return DiagResult{false, "docker not found"}
19		}
20		cmdArgs := append([]string{"run", "--rm", "--network", "host", image}, args...)
21		cmd := exec.Command("docker", cmdArgs...)
22		output, err := cmd.CombinedOutput()
23		out := strings.ReplaceAll(string(output), "\r\n", "\n")
24		out = strings.ReplaceAll(out, "\r", "\n")
25		out = strings.TrimSpace(out)
26		return DiagResult{err == nil, out}
27	}
28	
29	// RunPing executes ping -c 3 <target> in the network multitool container
30	func RunPing(image, target string) DiagResult {
31		return runDiagHost(image, []string{"ping", "-c", "3", target})
32	}
33	
34	// RunDNS executes dig <target> [@dnsServer] in the network multitool container.
35	// If dnsServer is empty, the container's default resolver is used.
36	func RunDNS(image, target, dnsServer string) DiagResult {
37		args := []string{"dig", target}
38		if strings.TrimSpace(dnsServer) != "" {
39			args = append(args, "@"+strings.TrimSpace(dnsServer))
40		}
41		return runDiagHost(image, args)
42	}
43	
44	// RunReverseDNS executes dig -x <ip> [@dnsServer] for PTR (reverse DNS) lookup.
45	// If dnsServer is empty, the container's default resolver is used.
46	func RunReverseDNS(image, ip, dnsServer string) DiagResult {
47		args := []string{"dig", "-x", ip}
48		if strings.TrimSpace(dnsServer) != "" {
49			args = append(args, "@"+strings.TrimSpace(dnsServer))
50		}
51		return runDiagHost(image, args)
52	}
