60	// The exit code is ignored: tcptraceroute returns non-zero when the destination is not reached within
61	// the hop limit, but the partial trace is still useful output.
62	func RunTCPTraceroute(image, target, port string) DiagResult {
63		if _, err := exec.LookPath("docker"); err != nil {
