597		var result []FirewallChain
598		var current *FirewallChain
599	
600		for line := range strings.SplitSeq(raw, "\n") {
601			line = strings.TrimSpace(line)
602			if line == "" {
603				continue
604			}
605			// Chain header: "Chain INPUT (policy ACCEPT)" or "Chain DOCKER-USER (1 references)"
606			if strings.HasPrefix(line, "Chain ") {
607				if current != nil {
608					result = append(result, *current)
609				}
610				fields := strings.Fields(line)
611				chain := FirewallChain{Name: fields[1], Policy: "n/a"}
612				// Extract policy from "(policy ACCEPT)"
613				if len(fields) >= 4 && fields[2] == "(policy" {
614					chain.Policy = strings.TrimSuffix(fields[3], ")")
615				}
616				current = &chain
617				continue
618			}
619			// Skip the column header line ("num  target  prot ...")
620			if strings.HasPrefix(line, "num") || strings.HasPrefix(line, "target") {
621				continue
622			}
623			// Count rule lines (non-empty, non-header lines within a chain block)
624			if current != nil {
625				current.Rules++
626			}
627		}
628		if current != nil {
629			result = append(result, *current)
630		}
