637		var current *FirewallChain
638	
639		for line := range strings.SplitSeq(raw, "\n") {
640			trimmed := strings.TrimSpace(line)
641			if trimmed == "" {
642				continue
643			}
644			// Chain block: "\tchain input {"
645			if strings.HasPrefix(trimmed, "chain ") {
646				if current != nil {
647					result = append(result, *current)
648				}
649				fields := strings.Fields(trimmed)
650				current = &FirewallChain{Name: fields[1], Policy: "n/a"}
651				continue
652			}
653			if current == nil {
654				continue
655			}
656			// Policy line: "type filter hook input priority 0; policy accept;"
657			if strings.HasPrefix(trimmed, "type ") {
658				for part := range strings.SplitSeq(trimmed, ";") {
659					part = strings.TrimSpace(part)
660					if policy, ok := strings.CutPrefix(part, "policy "); ok {
661						current.Policy = strings.ToUpper(policy)
662					}
663				}
664				continue
665			}
666			// End of chain block
667			if trimmed == "}" {
668				result = append(result, *current)
669				current = nil
670				continue
671			}
672			// Count rule lines
673			current.Rules++
674		}
675		if current != nil {
676			result = append(result, *current)
677		}
678		return result
679	}

